'use strict';

// MODULES //

var gunzipSync = require( 'node:zlib' ).gunzipSync;
var canonicalBytes = require( '@data-apis/canonical/bytes' );


// MAIN //

/**
* Asserts that stored bytes use deterministic serialization and gzip settings.
*
* @param {Buffer} bytes - stored bytes
* @param {Object} envelope - parsed stored record
* @throws {Error} if bytes differ
*/
function assertCanonicalGzip( bytes, envelope ) {
	var decompressed;

	if ( bytes.length < 10 || bytes[ 0 ] !== 0x1f || bytes[ 1 ] !== 0x8b || bytes[ 2 ] !== 0x08 ) {
		throw new Error( 'Stored envelope is not a gzip stream' );
	}
	if ( bytes[ 3 ] !== 0 || bytes.readUInt32LE( 4 ) !== 0 ) {
		throw new Error( 'Stored gzip header contains non-deterministic metadata' );
	}
	decompressed = gunzipSync( bytes, {
		'maxOutputLength': 55 * 1024 * 1024
	} );
	if ( !decompressed.equals( canonicalBytes( envelope ) ) ) {
		throw new Error( 'Stored envelope does not use canonical JSON serialization' );
	}
}


// EXPORTS //

module.exports = assertCanonicalGzip;
